// Purpose: ROW-017 (REQ-009) — through the check endpoint, a misspelled first word of a sentence
// (Buscamso, fresh names) is flagged after every sentence opening, and a capitalised mid-sentence word
// whose accented form is a dictionary word (Gestion, Informatica, a generated sample) is flagged.
// Provenance: hand-authored from REQ-009's fail-if examples, A-012, A-031 and A-036; the accent sample
// generated by the dictionary oracle (accentPopulation, title-cased and checked); fresh names per run; no
// expected value comes from the product.
//
// Test argument
// ROW-017 promise: a misspelled first word of a sentence is flagged, and a capitalised mid-sentence
//   word whose accent-restored form is a dictionary word is flagged (REQ-009 fail-if arms 2 and 4;
//   A-012 "a sentence-initial word is checked"; A-031 sentence starts: text start, after . ? ! or …;
//   A-036 "when the same word with its accents restored is in the dictionary it is flagged").
// ROW-017 wrong product: a proper-noun rule that exempts every capitalised unknown word, so "Buscamso"
//   opening the offer and "Gestion" in "Analista de Gestion" pass; one that knows only ". " as a
//   sentence end, so a misspelling after "?", "!" or "…" is taken as a name; one that restores accents
//   only for a hand-listed few words, so the generated sample's "Administracion" passes.
// ROW-017 given: Buscamso and fresh names opening the text and after ". ", "? ", "! ", "… " and
//   "... "; "Analista de Gestion", "Informatica" and ~30 generated title-cased accent-stripped words
//   mid-sentence; decoys in the same text: Buscamos opening sentences, the correctly accented title-case
//   forms mid-sentence, and fresh names mid-sentence (all unflagged); when: POST /api/check; then:
//   exactly the misspelled openings and the accent-stripped capitals are flagged, at their offsets.
// ROW-017 controls: the lower-case accent-stripped words (gestion, informatica, the sample) mid-sentence
//   are flagged — they are misspellings to the product whatever the capital rule says.
// ROW-017 technique: every sentence opening A-031 names, the row's examples, and a generated sample over
//   the dictionary's accented words (fresh each run); exact comparison with one-accent-apart decoys.
// cases: ROW-017 target=ROW-017-misspelled-sentence-openings-and-accent-restorable-capitals-flagged control=ROW-017-control-lower-case-accent-stripped-words-flagged

import { test } from '@playwright/test';
import { accentPopulation, asActor, freshRandom, isDictionaryWord, type Rng } from './harness';
import { Offer, expectExact, fillers, freshName, requireDictionary, requireNotDictionary, titleCase } from './names-terms-helpers';

const OPENINGS = ['. ', '? ', '! ', '… ', '... '];

/** Accent pairs whose title-cased stripped form is no dictionary word while the title-cased accented form is. */
function capitalSample(rng: Rng, n: number) {
  return rng
    .shuffle(accentPopulation())
    .filter((p) => !isDictionaryWord(titleCase(p.stripped)) && isDictionaryWord(titleCase(p.word)))
    .slice(0, n);
}

test('ROW-017-misspelled-sentence-openings-and-accent-restorable-capitals-flagged', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  requireNotDictionary(['Buscamso', 'Gestion', 'Informatica'], 'ROW-017 named misspellings');
  requireDictionary(['Buscamos', 'Gestión', 'Informática'], 'ROW-017 named decoys');
  const sample = capitalSample(rng, 30);

  const o = new Offer().flag('Buscamso', 'Buscamso opening the text').put(' ' + fillers(rng, 3));
  // misspelled openings after every sentence end, and correct openings as decoys
  for (const end of rng.shuffle([...OPENINGS, ...OPENINGS])) {
    o.put(end).flag(rng.int(3) === 0 ? 'Buscamso' : freshName(rng), `misspelled opening after ${JSON.stringify(end)}`).put(' ' + fillers(rng, 2));
    o.put(rng.pick(OPENINGS)).keep('Buscamos', 'Buscamos opening a sentence').put(' ' + fillers(rng, 2));
  }
  // the named mid-sentence examples
  o.put(', analista de ').flag('Gestion', 'Gestion in Analista de Gestion').put(' ' + fillers(rng, 2) + ' ').flag('Informatica', 'Informatica mid-sentence');
  o.put(' ' + fillers(rng, 1) + ' ').keep('Gestión', 'Gestión mid-sentence').put(' ' + fillers(rng, 1) + ' ').keep('Informática', 'Informática mid-sentence');
  // the generated sample, each beside its correct form and a fresh name
  for (const p of sample) {
    o.put(' ' + fillers(rng, 1 + rng.int(2)) + ' ').flag(titleCase(p.stripped), 'accent-stripped capital mid-sentence');
    o.put(' ' + fillers(rng, 1) + ' ').keep(titleCase(p.word), 'accented capital mid-sentence');
    if (rng.int(3) === 0) o.put(' ' + fillers(rng, 1) + ' ').keep(freshName(rng), 'fresh name mid-sentence');
  }
  o.put('.');
  await expectExact(o, `ROW-017: misspelled sentence openings and capitalised mid-sentence words whose accented form is a dictionary word are flagged (seed ${rng.seed})`);
});

test('ROW-017-control-lower-case-accent-stripped-words-flagged', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const o = new Offer().put(fillers(rng, 2, { capital: true }) + ' ').flag('gestion', 'gestion lower case').put(' ' + fillers(rng, 1) + ' ').flag('informatica', 'informatica lower case');
  for (const p of capitalSample(rng, 4)) o.put(' ' + fillers(rng, 1) + ' ').flag(p.stripped, 'accent-stripped word lower case');
  o.put(' ' + fillers(rng, 2) + '.');
  await expectExact(o, `ROW-017 control: the accent-stripped words in lower case mid-sentence are flagged (seed ${rng.seed})`);
});
